// src/data/atlas.ts — Rome c. AD 113. Self-contained (no imports). REAL meters; local frame: origin = Miliarium Aureum, +x EAST, +z SOUTH; elevations = m ASL at ancient ground level.
//
// GENERATED ONCE from docs/research/topography-terrain.md + topography-landmarks.md (+ OSM checks), then hand-maintained:
// edit this file directly. See docs/ATLAS.md for conventions, sources, coverage and known uncertainties.
// Re-render the overview map with: node --experimental-strip-types scripts/atlas/render-atlas.mjs  (writes docs/atlas.svg)
//
// Confidence: 'high' = surveyed remains (OSM, +-5-15 m); 'medium' = excavation / strong topographic argument (+-20-40 m);
// 'low' = placed by best guess (+-50-150 m). Anything 'low' may move.

export type P2 = readonly [x: number, z: number];

export const ORIGIN: { lat: number; lon: number; note: string } = {
  lat: 41.89258,
  lon: 12.48438,
  note: 'Miliarium Aureum (OSM way 131557543). x = (lon - lon0) * 111320 * cos(lat0) ~ (lon - lon0) * 82866.4 (east); z = -(lat - lat0) * 110574 (south).',
};

export const WORLD_SCALE = 0.6; // uniform game scale for layout + landmarks (game code applies it)

export const BASE_ELEVATION: number = 13; // default ground elevation for low ground not covered by a Lowland

export interface Hill {
  id: string;
  name: string;
  latin: string;
  outline: P2[]; // plateau edge, ~8-16 pts
  summit: number;
  plateau: number;
  slope: number; // horizontal metres from plateau edge to valley floor
  cliffs?: { a: P2; b: P2; note?: string }[];
  notes?: string;
  /** 'hill' = a named hill; 'terrace' = a DEM-derived upper/outer contour that only refines the terrain blend. */
  kind?: 'hill' | 'terrace';
  /** For terraces: the named hill they belong to. */
  parent?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Lowland { id: string; name: string; polygon: P2[]; elevation: number; notes?: string }
export interface River {
  id: string;
  name: string;
  centerline: P2[];
  width: number[]; // per centerline point
  waterLevel: number;
  bankHeight: number;
  kind?: 'river' | 'canal';
  notes?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Island { id: string; name: string; outline: P2[]; elevation: number; notes?: string }
export interface Road {
  id: string;
  name: string;
  latin?: string;
  kind: 'via' | 'clivus' | 'vicus' | 'street' | 'path' | 'stairs';
  points: P2[];
  width: number;
  paving: 'basalt' | 'gravel' | 'dirt' | 'steps';
  confidence: 'high' | 'medium' | 'low';
}
export interface Wall {
  id: string;
  name: string;
  points: P2[];
  state: 'intact' | 'partial' | 'ruinous' | 'built-over';
  height: number; // what stands in 113 (the original Servian wall was ~10 m)
  thickness: number;
  /** Earth bank behind the wall (the agger), metres wide. */
  rampartWidth?: number;
  notes?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Gate {
  id: string;
  name: string;
  latin: string;
  at: P2;
  rotation: number; // bearing the gate's outer face looks toward (outward from the old city), clockwise from north
  state: string;
  /** When the gate is also built as a LANDMARK (standing structure), its landmark id — wall builders should skip it. */
  landmarkId?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Aqueduct {
  id: string;
  name: string;
  latin: string;
  points: P2[];
  channelElevation: number[]; // m ASL of the (top) channel at each point; arcade height = channel - ground
  kind: 'arcade' | 'underground' | 'mixed';
  built: string;
  notes?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Bridge {
  id: string;
  name: string;
  latin: string;
  a: P2; // left (city / E-N) bank end
  b: P2; // right (W-S) bank end
  width: number;
  arches: number; // 0 = timber trestle bridge
  material: string;
  built: string;
  length?: number;
  notes?: string;
  confidence?: 'high' | 'medium' | 'low';
}
export interface Region {
  id: string;
  number: number;
  /** OUT-OF-WORLD map label: the 4th-century Regionary name (Notitia / Curiosum). In AD 113 the regions are known only by number. */
  name: string;
  /** In-world designation ('Regio IV'); in speech, "the Fourth Region". */
  latin: string;
  polygon: P2[];
  character: string;
  density: number; // 0-1
  wealth: number; // 0-1
  typical: string[];
}
export type LandmarkCategory = 'temple' | 'forum' | 'basilica' | 'arch' | 'column' | 'amphitheatre' | 'circus' | 'theatre' | 'odeum' | 'stadium' | 'baths' | 'palace' | 'house' | 'aqueduct' | 'gate' | 'market' | 'camp' | 'tomb' | 'monument' | 'fountain' | 'portico' | 'shrine' | 'prison' | 'warehouse' | 'library' | 'garden' | 'harbor' | 'curia' | 'other';
export type Footprint = { kind: 'rect'; w: number; d: number } | { kind: 'ellipse'; rx: number; rz: number } | { kind: 'circle'; r: number } | { kind: 'poly'; points: P2[] /* absolute frame coords */ };
// Orientation convention: in the building's local frame its main facade faces NORTH (-z), width w runs along x, depth d along z; then it is rotated by `rotation` degrees CLOCKWISE seen from above (0 = facade faces north, 90 = east, 180 = south, 270 = west). For ellipses, rx is the long axis before rotation (along x), so a long axis running east-west has rotation 0. (Three.js: object.rotation.y = -rotation * PI/180.)
// Special cases used below: circles -> rotation = bearing the door faces; theatres/odea -> the facade is the curved cavea (stage at the back);
// circuses/stadia -> the facade is the straight (carceres) end, curved end at the back; fora -> the direction the main temple / entrance faces.
export interface Landmark {
  id: string;
  name: string;
  latin: string;
  category: LandmarkCategory;
  center: P2;
  rotation: number;
  footprint: Footprint;
  height: number; // total height above its own ground (top of roof / pediment / statue)
  baseElevation?: number; // m ASL of the building pad (or of the lowest main level for 'slope' sites)
  region: string; // Region id
  status113: 'complete' | 'new' | 'under-construction' | 'damaged' | 'ruin' | 'remodeled';
  dates: string;
  description: string;
  builderNotes: string;
  priority: 1 | 2 | 3;
  confidence: 'high' | 'medium' | 'low';
  /** Free-text qualifier when status113 needs one (e.g. 'removed 96', 'walled up', 'may postdate 113'). */
  statusNote?: string;
  /**
   * How the building meets the ground. 'pad' (default): flatten a pad at baseElevation.
   * 'slope': terraced into a hillside, do NOT flatten the whole footprint (use the terrain under it).
   * 'open': open area / garden / district / water, no solid mass. 'underground': below the surface.
   */
  siting?: 'pad' | 'slope' | 'open' | 'underground';
  /** Id of the landmark whose footprint contains this one (e.g. a temple inside its forum). */
  within?: string;
  /**
   * OUT-OF-WORLD note for the codex / map: modern or later facts no Roman of 113 could know (what the site became,
   * later anecdotes, modern labels). "description" stays what a Roman of 113 could know; never voice codexNote in dialogue.
   */
  codexNote?: string;
}


